import json,pathlib,copy
from bs4 import BeautifulSoup
r=pathlib.Path('work/research-2026');p=json.load(open(r/'reviewed.json'));xs=json.load(open(r/'verified-sites147-next100-review.json'));before={};dec=[]
assert not (r/'featured145-before.json').exists()
fix={13:'Develops rotary engines for vehicle propulsion and power generation, with a focus on military and aerospace applications.',14:'Develops laser-based isotope-separation technology, including uranium enrichment applications.',29:'Develops virtual-reality flight simulators for pilot training.',33:'Operates a coal-fired power facility in Maidsville, West Virginia; its parent lists the facility at 710 MW.',35:'A nonprofit providing adapted tennis, pickleball and padel programs for people with autism and other developmental disabilities, plus training for coaches and therapists.',47:'Harvests, processes and distributes seafood, including squid, scallops and finfish, for restaurants, distributors and retailers.',49:'Develops reusable satellites designed to return payloads from orbit.',62:'Provides aviation maintenance, logistics and operational support for U.S. and partner-government customers.',72:'Develops rare-earth mineral-processing and purification technology in Long Beach, California.',74:'Supplies firearms accessories, including magazines, stocks, grips, sights and mounting systems.',91:'Advocates federal support for maritime fuels and related infrastructure in U.S. ports and marinas.',97:'Provides collaboration, messaging and workflow-automation software for private-cloud, on-premises and isolated computing environments.'}
special={3:'Official shipping-services site names Liberty Global Logistics, LLC in the footer and describes ocean freight and cargo services.',13:'Official LiquidPiston site describes rotary-engine development. Advertised efficiency, power, quietness and market size are not independently validated.',14:'Official site explicitly identifies LIS Technologies Inc. and laser isotope separation. Patents, cost advantages and enrichment performance are not independently verified.',15:'Official marine-chain site names Lister Chain & Forge, Inc. and describes chain, anchors, fittings and inspection services.',19:'Official Lithios body describes electrochemical extraction from lithium brines. Advertised recovery and cost reductions are not independently established.',29:'Official Loft Dynamics body describes VR flight simulators. Regulatory qualifications are not generalized to all products or independently checked in this pass.',33:'Official Mountain State Energy Holdings site explicitly names Longview Power among its affiliates and describes the Maidsville coal facility as 710 MW. This corrects the prior 700 MW description; environmental marketing is not adopted.',35:'Official Love Serving Autism body explicitly describes it as a national nonprofit and details adapted racquet-sport programs and professional training.',42:'Not applied.',45:'Official Lunar Outpost body names Lunar Outpost Inc. and describes lunar robotics development. Future launch dates and guaranteed human safety are not treated as established operating outcomes.',47:'Official Lund Fisheries body describes harvesting, processing and seafood distribution, including both wild-caught and farm-raised products. The description no longer implies every product is wild-caught.',49:'Official Lux Aeterna body names Lux Aeterna Space Inc. and describes reusable-satellite development. Future mission capability is not an established recurring service.',56:'Official Lytton Rancheria body identifies the Pomo tribal government in Sonoma County and explicitly states federal recognition. Source filing IDs remain separate in this pass.',57:'Official Lytton Rancheria body identifies the Pomo tribal government in Sonoma County and explicitly states federal recognition. Source filing IDs remain separate in this pass.',58:'Official Lytx body describes fleet video telematics and names Lytx, Inc. in trademark information. Safety and cost-reduction claims are not independently established.',60:'Official M Financial Group body describes financial-services design and distribution through independent member firms. It does not make all member firms a single legal entity.',63:'Official Mach Industries body describes aerospace and defense systems and names Mach Industries Inc. Production targets are not established manufacturing output.',72:'Official Maglut body describes rare-earth processing development and pilot-scale work in Long Beach. Future demonstration deployment is not commercial-scale operations.',74:'Official Magpul storefront lists branded firearm accessories and names Magpul Industries Corp. in its footer.',76:'Official Mahzi body describes therapies under development for rare genetic neurodevelopmental disorders; approved or effective treatments are not inferred.',80:'Official Malnutrition Advocacy Fund body describes advocacy for childhood-malnutrition products and public support. Medical efficacy and economic-impact claims are not independently verified.',84:'Official Mantel body names Mantel Capture, Inc. and describes high-temperature carbon-capture material development. Efficiency and commercial viability claims are not independently established.',85:'Official Mantis product catalog describes commercial training systems and names Mantis Tech, LLC at its Oswego address.',88:'Official Marathon Targets body describes autonomous robotic targets for live-fire training. Advertised scale and effectiveness are not independently established.',90:'Official Mariner Finance body describes personal lending and names Mariner Finance, LLC with its Nottingham address. Product prices and lending terms are not generalized.',91:'Official coalition About body describes its advocacy for maritime fuels and related infrastructure. Standalone tax status is not established.',96:'Official Matrix Medical Network body describes in-home assessments and care management for health-plan members. Advertised health and cost outcomes are not independently verified.',97:'Official Mattermost body describes collaboration software and names Mattermost, Inc. in the footer.'}
for n,v in enumerate(xs):
 if v['decision']!='confirmed' or n in [42,66]:continue
 i=v['id'];assert p[i]['name']==v['original_name'] and p[i]['review_outcome']!='confirmed';before[i]=copy.deepcopy(p[i]);note=special.get(n,'Official organization body text identifies this organization and supports the activity summarized. Existing ownership evidence is retained without inferring additional ownership from its name.')
 p[i].update(description=fix.get(n,v['description']),notes=note,identity_evidence=note,review_outcome='confirmed',checked_at='2026-09-13',as_of='2026-09-13')
 
 if n==35:p[i]['ownership']='Nonprofit'
 if n==33:p[i]['ownership']='Subsidiary'
 e=v['fetched_evidence'][0];assert e['http_status']==200
 s=BeautifulSoup(open(e['cache_path']).read(),'html.parser')
 for t in s(['script','style','nav','header']):t.decompose()
 body=' '.join(s.stripped_strings)
 ss={s['url']:s for s in p[i]['sources']};ss[e['url']]={'url':e['url'],'label':'Official organization evidence','claim':note};p[i]['sources']=list(ss.values());dec.append(dict(id=i,name=p[i]['name'],decision='confirmed',notes=note,fetched_evidence=v['fetched_evidence'],reviewed_body=body))
(r/'featured145-before.json').write_text(json.dumps(before,indent=2)+'\n');(r/'featured145-decisions.json').write_text(json.dumps(dec,indent=2)+'\n')
(r/'featured145-deferred.json').write_text(json.dumps([dict(id=xs[n]['id'],name=xs[n]['original_name'],reason=why) for n,why in [(42,'Copyright names LTSE Services but does not substantiate its activity separately from the exchange ecosystem.'),(66,'Venue schedule identifies Madison Square Garden arena; exact lobbying corporate entity is not established.')]],indent=2)+'\n')
for f in [r/'reviewed.json',pathlib.Path('outputs/2026-research-trial/profiles.json')]:f.write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n')
pathlib.Path('lobbying-map/research/reviewed-2026.json').write_text(json.dumps(p,ensure_ascii=False));print(len(dec),'identity confirmations saved')
